// v1.17 F7 rule 1: CostAwareRouter::plan_sweep parity with the Python
// reference (tests/golden/expected_f7_sor_sweep.json, generated by
// python/tools/make_golden_f7.py --only r01_sor_sweep): fixed three-venue
// books and the sampled real slice, canonical bytes equal.

#include <gtest/gtest.h>

#include "f7_util.hpp"
#include "iap/sor/sor_v2.hpp"

namespace {

using namespace iap_f7;

Value run_queries(iap::CostAwareRouter& r, const iap::ConsolidatedBook& book,
                  const Value& queries) {
    Array out;
    for (const Value& q : queries.as_array()) {
        r.options() = router_options_from(q.at("options"));
        const auto cands = candidates_from(q.at("candidates"));
        Object res;
        try {
            const auto ch = r.plan_sweep(
                book, static_cast<std::uint8_t>(q.at("side").as_int64()),
                q.at("qty").as_int64(), q.at("ts").as_int64(),
                opt_i64(q.at("limit_ticks")), cands.has_value() ? &*cands : nullptr,
                opt_num(q.at("tick")));
            Array rows;
            for (const auto& c : ch) {
                rows.push_back(Value(Array{vi(c.venue_id), vi(c.price_ticks), vi(c.qty),
                                           vi(c.send_offset_ns), vi(c.arrival_offset_ns)}));
            }
            res["children"] = Value(std::move(rows));
        } catch (const std::invalid_argument& e) {
            res["error"] = vs(e.what());
        }
        out.push_back(Value(std::move(res)));
    }
    return Value(std::move(out));
}

void record_fills(iap::FeeLedger& ledger, const Value& fills) {
    for (const Value& f : fills.as_array()) {
        ledger.record(static_cast<std::uint16_t>(f.at(0).as_uint64()), f.at(1).as_int64(),
                      f.at(2).as_int64(), f.at(3).as_bool());
    }
}

TEST(F7SorSweep, FixedVectors) {
    const Value g = load_golden("expected_f7_sor_sweep.json");
    const Array& scen = g.at("inputs").at("fixed").as_array();
    Array got;
    for (const Value& s : scen) {
        const auto models = venue_models_from(s.at("venues"));
        iap::ConsolidatedBook book(7);
        for (const auto& ev : events_from_rows(s.at("events"))) book.apply(ev);
        iap::FeeLedger ledger(models);
        record_fills(ledger, s.at("ledger_fills"));
        iap::CostAwareRouter r(models, iap::RouterOptions{},
                               sor_options_from(s.at("sor_options")), &ledger);
        got.push_back(run_queries(r, book, s.at("queries")));
    }
    expect_canonical_eq(g.at("expected").at("fixed"), Value(std::move(got)), "fixed");
}

TEST(F7SorSweep, RealSliceSamples) {
    const Value g = load_golden("expected_f7_sor_sweep.json");
    const Value& in = g.at("inputs").at("slice");
    ASSERT_EQ(in.at("sample_every").as_int64(), kSampleEvery);
    ASSERT_EQ(in.at("prefix_events").as_int64(), kSlicePrefix);
    const auto models = venue_models_from(in.at("venues"));
    iap::FeeLedger ledger(models);
    iap::CostAwareRouter r(models, iap::RouterOptions{}, sor_options_from(in.at("sor_options")),
                           &ledger);
    const auto events = read_slice();
    ASSERT_EQ(events.size(), 65132u);
    iap::ConsolidatedBook book(kSliceInstrument);
    iap::RouterOptions price, price_none, all_in;
    price_none.stagger = iap::StaggerMode::NONE;
    all_in.sweep_rank = iap::SweepRank::ALL_IN;
    Array rows;
    for (std::size_t k = 1; k <= events.size(); ++k) {
        book.apply(events[k - 1]);
        if (!is_sample(k)) continue;
        const std::int64_t ts = events[k - 1].exchange_ts;
        const iap::OrderBook& vb = book.books().at(kSliceVenue);
        const auto ba = vb.best_ask();
        const auto bb = vb.best_bid();
        Array res;
        auto one = [&](std::uint8_t side, std::int64_t qty, const iap::RouterOptions& o,
                       std::optional<std::int64_t> limit) {
            r.options() = o;
            Object e;
            try {
                const auto ch = r.plan_sweep(book, side, qty, ts, limit, nullptr, kSliceTick);
                Array c;
                for (const auto& x : ch) {
                    c.push_back(Value(Array{vi(x.venue_id), vi(x.price_ticks), vi(x.qty),
                                            vi(x.send_offset_ns), vi(x.arrival_offset_ns)}));
                }
                e["children"] = Value(std::move(c));
            } catch (const std::invalid_argument& ex) {
                e["error"] = vs(ex.what());
            }
            res.push_back(Value(std::move(e)));
        };
        one(0, 5000, price, std::nullopt);
        one(1, 5000, all_in, std::nullopt);
        one(0, 3000, all_in, ba.has_value() ? std::optional<std::int64_t>(ba->first + 2) : std::nullopt);
        one(1, 800, price_none, bb.has_value() ? std::optional<std::int64_t>(bb->first) : std::nullopt);
        Object row;
        row["k"] = vi(static_cast<std::int64_t>(k));
        row["ts"] = vi(ts);
        row["results"] = Value(std::move(res));
        rows.push_back(Value(std::move(row)));
    }
    expect_canonical_eq(g.at("expected").at("slice"), Value(std::move(rows)), "slice");
}

}  // namespace
